const entrada = $('Formulário').first().json;
const texto = $input.first().json.content.parts[0].text;
const vaga = JSON.parse(texto.replace(/```json|```/g, "").trim());

if (!entrada["Seu curriculo"]) {
  throw new Error("Campo do currículo vazio. Campos recebidos: " + Object.keys(entrada).join(", "));
}
if (!vaga.cargo) {
  throw new Error("A IA não extraiu a vaga. Confira se o texto chegou ao prompt.");
}

return [{ json: { vaga, cv_texto: entrada["Seu curriculo"], link: (entrada["Link da vaga"] || "").trim() } }];

const entrada = $('Interpretar vaga').first().json; // nome do PRIMEIRO Code
const texto = $input.first().json.content.parts[0].text;
const analise = JSON.parse(texto.replace(/```json|```/g, "").trim());
const sugestoes = analise.sugestoes ?? [];

const valor = { atende: 1, parcial: 0.5, nao_atende: 0 };
let pontos = 0;
let total = 0;
for (const r of analise.requisitos) {
  if (r.categoria !== "tecnico") continue; // só itens técnicos entram na nota
  const peso = r.tipo === "obrigatorio" ? 2 : 1; // obrigatório vale o dobro
  pontos += (valor[r.status] ?? 0) * peso;
  total += peso;
}
const nota = total ? Math.round((pontos / total) * 100) : 0;

const icone = { atende: "✅", parcial: "🟡", nao_atende: "❌" };
const tecnicos = analise.requisitos.filter(r => r.categoria === "tecnico");
const comportamentais = analise.requisitos.filter(r => r.categoria === "comportamental");
const elegibilidade = analise.requisitos.filter(r => r.categoria !== "tecnico" && r.categoria !== "comportamental");

const linhas = [
  `Vaga: ${entrada.vaga.cargo}`,
  ...(entrada.link ? [`Link: ${entrada.link}`] : []),
  `Aderência técnica: ${nota}/100`,
  "",
  "Requisitos técnicos:",
  ...tecnicos.map(r => `${icone[r.status] ?? "❔"} ${r.item} (${r.tipo})${r.evidencia ? " - " + r.evidencia : ""}`),
];
if (comportamentais.length) {
  linhas.push("", "Comportamentais (não entram na nota):", ...comportamentais.map(r => `• ${r.item}`));
}
if (elegibilidade.length) {
  linhas.push("", "Elegibilidade (não entra na nota):", ...elegibilidade.map(r => `${icone[r.status] ?? "❔"} ${r.item}${r.evidencia ? " - " + r.evidencia : ""}`));
}
if (sugestoes.length) {
  linhas.push("", "Sugestões:", ...sugestoes.map(s => `• ${s}`));
}

return [{ json: {
  cargo: entrada.vaga.cargo,
  nota,
  requisitos: analise.requisitos,
  sugestoes,
  mensagem: linhas.join("\n"),
} }];

const entrada = $('Formulário').first().json;
const link = (entrada["Link da vaga"] || "").trim();

if (!/^https?:\/\//i.test(link)) {
  throw new Error("Informe o texto da vaga ou um link válido (começando com http).");
}

const resposta = $input.first().json;
const html = String(resposta.html ?? resposta.data ?? "");

const texto = html
  .replace(/<script[\s\S]*?<\/script>/gi, " ")
  .replace(/<style[\s\S]*?<\/style>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ")
  .replace(/&amp;/g, "&")
  .replace(/\s+/g, " ")
  .trim()
  .slice(0, 12000);

if (texto.length < 300) {
  throw new Error('Não consegui ler o conteúdo do link (o site pode ter bloqueado ou carregar a vaga por JavaScript). Cole o texto da vaga no campo "Texto da vaga".');
}

return [{ json: { ...entrada, "Texto da vaga": texto } }];
